CREATE TABLE IF NOT EXISTS folders (id UUID PRIMARY KEY, user_id UUID NOT NULL, parent_id UUID REFERENCES folders(id), name VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,parent_id,name));
CREATE TABLE IF NOT EXISTS files (id UUID PRIMARY KEY, user_id UUID NOT NULL, folder_id UUID REFERENCES folders(id), name VARCHAR(255) NOT NULL, mime_type VARCHAR(255) NOT NULL, size_bytes BIGINT NOT NULL CHECK(size_bytes >= 0), sha256 CHAR(64) NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('pending','processing','ready','failed','deleted')), object_key TEXT NOT NULL UNIQUE, idempotency_key VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS file_quotas (user_id UUID PRIMARY KEY, quota_bytes BIGINT NOT NULL DEFAULT 0 CHECK(quota_bytes >= 0), max_files BIGINT NOT NULL DEFAULT 0 CHECK(max_files >= 0), used_bytes BIGINT NOT NULL DEFAULT 0 CHECK(used_bytes >= 0), file_count BIGINT NOT NULL DEFAULT 0 CHECK(file_count >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS file_audit_log (id UUID PRIMARY KEY, user_id UUID NOT NULL, file_id UUID, action VARCHAR(64) NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_files_user_folder ON files(user_id,folder_id) WHERE status <> 'deleted';
